8: static inline uint8_t base64_value(uint8_t c) {
9:   if (c >= 'A' && c <= 'Z') return (uint8_t)(c - 'A');
10:   if (c >= 'a' && c <= 'z') return (uint8_t)(c - 'a' + 26);
11:   if (c >= '0' && c <= '9') return (uint8_t)(c - '0' + 52);
12:   if (c == '+') return 62;
13:   if (c == '/') return 63;
14:   return 255;
15: }
