20:   size_t written = 0;
21:   *outlen = 0;
22:   if ((srclen & 3u) != 0) return 0;
23:   for (size_t i = 0; i < srclen; i += 4) {
24:     const uint8_t a = base64_value(s[i]);
25:     const uint8_t b = base64_value(s[i + 1]);
26:     const int last = (i + 4 == srclen);
27:     if (a > 63 || b > 63) return 0;
28:     if (s[i + 2] == '=') {
29:       if (!last || s[i + 3] != '=') return 0;
30:       out[written++] = (char)((a << 2) | (b >> 4));
31:       continue;
32:     }
33:     const uint8_t c = base64_value(s[i + 2]);
