50: extern "C" void scalar_base64_encode(const char *src, size_t srclen,
51:                                      char *out, size_t *outlen) {
52:   static const char alphabet[] =
53:       "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
54:   const uint8_t *s = (const uint8_t *)src;
55:   size_t i = 0, written = 0;
56:   while (srclen - i >= 3) {
57:     const uint32_t v = ((uint32_t)s[i] << 16) |
58:                        ((uint32_t)s[i + 1] << 8) | (uint32_t)s[i + 2];
59:     out[written++] = alphabet[(v >> 18) & 63];
60:     out[written++] = alphabet[(v >> 12) & 63];
61:     out[written++] = alphabet[(v >> 6) & 63];
62:     out[written++] = alphabet[v & 63];
63:     i += 3;
64:   }
65:   if (i < srclen) {
66:     const int have_second = (srclen - i > 1);
67:     const uint32_t v = ((uint32_t)s[i] << 16) |
68:                        (have_second ? ((uint32_t)s[i + 1] << 8) : 0);
69:     out[written++] = alphabet[(v >> 18) & 63];
70:     out[written++] = alphabet[(v >> 12) & 63];
71:     out[written++] = have_second ? alphabet[(v >> 6) & 63] : '=';
72:     out[written++] = '=';
73:   }
74:   *outlen = written;
75: }
